# backend.tf - 远程状态配置
terraform {
  backend "s3" {
    bucket         = "terraform-state-${var.environment}"
    key            = "terraform.tfstate"
    region         = "us-west-2"
    dynamodb_table = "terraform-state-lock"
    encrypt        = true

    # 状态锁定配置
    dynamodb_table_tags = {
      Name        = "terraform-state-lock"
      Environment = var.environment
      ManagedBy   = "terraform"
    }
  }
}

